# ── TEX: spark state, gas-giant band and ring tables, drone sprite frames ───
from math import sin
TEX = array.array('f', [0.0] * TEX_LEN)
for _i in range(64):        # planet bands by latitude
    _lat = _i / 32.0 - 1.0
    _b = 0.5 + 0.5 * sin(_lat * 14.0 + 1.6 * sin(_lat * 5.0))
    for _c, (_x, _y) in enumerate(((0.93, 0.62), (0.72, 0.38), (0.48, 0.28))):
        TEX[TEX_BAND // 4 + _i * 3 + _c] = _x * (1 - _b) + _y * _b
for _i in range(64):        # rings by (r/R)^2: premultiplied colour, alpha
    _r = sqrt(G_RR1 + (_i + 0.5) / G_RK)
    _al = 0.75 * (0.55 + 0.45 * sin(_r * 38.0) * sin(_r * 11.0 + 1.0))
    if abs(_r - 1.85) < 0.06:
        _al = 0.0
    for _c, _x in enumerate((0.95, 0.85, 0.70, 1.0)):
        TEX[TEX_RING // 4 + _i * 4 + _c] = _x * _al
# Fixed star field: NSTAR directions on the upper sky, brightness 0-255 (a few bright ones).
_sd = 20261008
def _rnd():
    global _sd
    _sd = (_sd * 1103515245 + 12345) & 0x7FFFFFFF
    return _sd / 0x7FFFFFFF
from math import cos, asin
for _i in range(NSTAR):
    _az = _rnd() * 6.2832
    _el = asin(0.12 + 0.75 * _rnd())          # roughly uniform over the dome, 7 deg and up
    _br = 60 + 140 * _rnd() ** 2
    if _rnd() < 0.12:
        _br = 230.0
    _o = TEX_STAR // 4 + _i * 4
    TEX[_o] = cos(_el) * sin(_az); TEX[_o + 1] = sin(_el); TEX[_o + 2] = cos(_el) * cos(_az); TEX[_o + 3] = _br
# Spotter drone sprite, 16x8, 4 frames: rotor wide/narrow x lamp red/green
# (green = your heading would score). '.' = transparent, L = lamp.
DRONE_ART = (
    ("cccccc....cccccc", "..cc........cc.."),
    ("...m........m...", "...m........m..."),
    ("...mmmmmmmmmm...", "...mmmmmmmmmm..."),
    ("..mggggggggggm..", "..mggggggggggm.."),
    ("..mgLLLLLLLLgm..", "..mgLLLLLLLLgm.."),
    ("..mggggggggggm..", "..mggggggggggm.."),
    ("...mmmmmmmmmm...", "...mmmmmmmmmm..."),
    (".......ww.......", ".......ww......."),
)
DRONE_PAL = {'c': (0.80, 0.88, 0.95), 'm': (0.22, 0.24, 0.30), 'g': (0.55, 0.58, 0.66),
             'w': (1.00, 0.90, 0.60)}
for _f in range(4):
    _rot = _f & 1
    _lamp = (1.6, 0.15, 0.05) if _f < 2 else (0.15, 1.6, 0.30)
    for _y in range(8):
        _row = DRONE_ART[_y][_rot]
        for _x in range(16):
            _ch = _row[_x]
            _col = _lamp if _ch == 'L' else DRONE_PAL.get(_ch, (-1.0, 0.0, 0.0))
            for _c in range(3):
                TEX[(TEX_DRONE + _f * TEX_FRAME) // 4 + (_y * 16 + _x) * 3 + _c] = _col[_c]
CTRL[C_TEX] = uctypes.addressof(TEX)
# ── Core 0: the whole renderer is one function

@micropython.asm_thumb
def rt_main(r0, r1) -> int:
    # r0 = CTRL (int32[]), r1 = FP (float32[]). Never returns until CTRL[0] != 0; returns frames.
    data(2, 0xE92D, 0x0F00)  # push.w {r8, r9, r10, r11} ;  callee-saved; r8/r9 = orb x-range
    data(2, 0xED2D, 0x8A10)  # vpush {s16-s31} ;  AAPCS: s16-s31 callee-saved
    vmov(s31, r0)
    mov(r7, r1)
    movwt(r1, 1020)
    add(r7, r7, r1)
    data(2, 0xF8D0, 0xA04C)  # ldr.w r10, [r0, #76] ;  r10 = TEX base for the whole function
    label(FRAME_LOOP)
    vmov(r0, s31)
    label(WAIT)
    ldr(r1, [r0, 0])
    cmp(r1, 0)
    bne_w(DONE)
    ldr(r1, [r0, 4])
    ldr(r2, [r0, 8])
    sub(r1, 1)
    cmp(r2, r1)
    blt(WAIT)
    ldr(r1, [r0, 12])
